query GetTranscriptsByGuest($guestEmail: String!) {
  transcripts(participant_email: $guestEmail) {
    id
    title
    date
    organizer_email
    participants
    duration
    sentences {
      text
      speaker_name
      start_time
      end_time
    }
    summary {
      overview
      action_items
      keywords
    }
  }
}
